// SPDX-License-Identifier: Apache-2.0

// Package gitleaksrules holds the credential rules of gitleaks (MIT, see LICENSE-gitleaks), pinned
// at one version, for the trace scrubber (ADR 0074, decision 6; issue #56).
//
// rules.json is generated by hack/gitleaks-rules.sh from the pinned release: the same rule list
// gitleaks builds its own config/gitleaks.toml from, with each rule's regular expression,
// keywords, entropy floor, secret group and allowlists. Do not edit it by hand. Updating it is a
// reviewed bump of GITLEAKS_VERSION in hack/versions.env; the scrub package tests generate a sample
// from each rule's expression, so no key-shaped string is committed.
package gitleaksrules

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

//go:embed rules.json
var rulesJSON []byte

// Allowlist is one allowlist of a rule, or a global one. A finding it matches is dropped.
type Allowlist struct {
	// MatchCondition is "AND" when every criterion must match, otherwise any one does.
	MatchCondition string `json:"matchCondition,omitempty"`
	// RegexTarget is what Regexes are tested against: "match" (the whole match), "line" (the line
	// holding the match) or empty (the secret).
	RegexTarget string   `json:"regexTarget,omitempty"`
	Regexes     []string `json:"regexes,omitempty"`
	// StopWords are tested against the secret, case-insensitively, as substrings.
	StopWords []string `json:"stopWords,omitempty"`
	// HasPaths and HasCommits say the allowlist also has a path or commit criterion. A trace has
	// neither, so an AND allowlist with one never matches. Older files lack the flags.
	HasPaths   bool `json:"hasPaths,omitempty"`
	HasCommits bool `json:"hasCommits,omitempty"`
}

// Rule is one gitleaks rule.
type Rule struct {
	ID    string `json:"id"`
	Regex string `json:"regex"`
	// SecretGroup is the capture group that holds the secret. Zero means the first capture group
	// that matched, or the whole match when the expression has none.
	SecretGroup int `json:"secretGroup,omitempty"`
	// Entropy is the Shannon entropy (bits per character) the secret must exceed; zero means none.
	Entropy float64 `json:"entropy,omitempty"`
	// Keywords are lower-case literals; a text without any of them cannot match the rule.
	Keywords   []string    `json:"keywords,omitempty"`
	Allowlists []Allowlist `json:"allowlists,omitempty"`
}

// Set is the whole rule set.
type Set struct {
	// Version is the gitleaks release the rules come from, without the leading v.
	Version string      `json:"version"`
	Global  []Allowlist `json:"global"`
	Rules   []Rule      `json:"rules"`
}

// Load decodes the embedded rule set.
func Load() (*Set, error) {
	var s Set
	if err := json.Unmarshal(rulesJSON, &s); err != nil {
		return nil, fmt.Errorf("gitleaksrules: %w", err)
	}
	return &s, nil
}
